using System.Globalization;
public static class Original
{
 public static decimal SeatPrice(string seatClass){string candidate=(seatClass??string.Empty).Trim();if(candidate.Equals("Standard",StringComparison.OrdinalIgnoreCase))return 50m;if(candidate.Equals("Premium",StringComparison.OrdinalIgnoreCase))return 90m;if(candidate.Equals("VIP",StringComparison.OrdinalIgnoreCase))return 140m;return 0m;}
 public static decimal CalculateTotal(string seatClass,int quantity){string candidate=(seatClass??string.Empty).Trim();decimal unit=candidate.Equals("Standard",StringComparison.OrdinalIgnoreCase)?50m:candidate.Equals("Premium",StringComparison.OrdinalIgnoreCase)?90m:candidate.Equals("VIP",StringComparison.OrdinalIgnoreCase)?140m:0m;if(unit==0m||quantity is <1 or >20)return 0m;decimal gross=decimal.Round(unit*quantity,2,MidpointRounding.AwayFromZero);decimal saving=quantity>=6?decimal.Round(gross*0.10m,2,MidpointRounding.AwayFromZero):0m;decimal reduced=gross-saving;decimal charge=reduced<=100m?5m:reduced<=500m?10m:20m;decimal levy=decimal.Round((reduced+charge)*0.08m,2,MidpointRounding.AwayFromZero);return decimal.Round(reduced+charge+levy,2,MidpointRounding.AwayFromZero);}
 public static string ProcessLine(string input){if(input==null)return "REJECTED: format";string[] parts=input.Split('|');if(parts.Length!=3)return "REJECTED: format";string attendee=parts[0].Trim(),seat=parts[1].Trim();string normalized=seat.Equals("Standard",StringComparison.OrdinalIgnoreCase)?"Standard":seat.Equals("Premium",StringComparison.OrdinalIgnoreCase)?"Premium":seat.Equals("VIP",StringComparison.OrdinalIgnoreCase)?"VIP":"";if(attendee.Length==0)return "REJECTED: name";if(normalized.Length==0)return "REJECTED: class";if(!int.TryParse(parts[2].Trim(),NumberStyles.Integer,CultureInfo.InvariantCulture,out int count)||count<1||count>20)return "REJECTED: quantity";decimal raw=(normalized=="Standard"?50m:normalized=="Premium"?90m:140m)*count;decimal subtotal=decimal.Round(raw,2,MidpointRounding.AwayFromZero),discount=count>=6?decimal.Round(raw*0.10m,2,MidpointRounding.AwayFromZero):0m,after=subtotal-discount,fee=after<=100?5m:after<=500?10m:20m,tax=decimal.Round((after+fee)*0.08m,2,MidpointRounding.AwayFromZero),total=decimal.Round(after+fee+tax,2,MidpointRounding.AwayFromZero);string[] output={"CONFIRMED: "+attendee,"Tickets: "+count.ToString(CultureInfo.InvariantCulture)+" x "+normalized,"Subtotal: $"+subtotal.ToString("0.00",CultureInfo.InvariantCulture),"Discount: $"+discount.ToString("0.00",CultureInfo.InvariantCulture),"Booking fee: $"+fee.ToString("0.00",CultureInfo.InvariantCulture),"Tax: $"+tax.ToString("0.00",CultureInfo.InvariantCulture),"Total: $"+total.ToString("0.00",CultureInfo.InvariantCulture)};return string.Join("\n",output);}
 public static string ProcessAll(string input){if(string.IsNullOrEmpty(input))return string.Empty;List<string> results=new();using StringReader source=new(input);string? current;while((current=source.ReadLine())!=null){if(string.IsNullOrWhiteSpace(current))continue;results.Add(ProcessLine(current));}return string.Join("\n",results);}
}
